gLx(){return"\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0645\u0631\u0641\u0642\u0627\u062a"},
gLy(){return"\u064a\u062a\u062d\u0643\u0645 \u0628\u0645\u0627 \u064a\u064f\u0633\u0645\u062d \u0644\u0644\u0645\u0648\u0638\u0641\u064a\u0646\u060c \u0648\u0627\u0644\u0623\u0637\u0628\u0627\u0621 \u0639\u0646\u062f \u0625\u0631\u0633\u0627\u0644 \u062d\u0627\u0644\u0629\u060c \u0628\u0625\u0631\u0641\u0627\u0642\u0647 \u0628\u0627\u0644\u062d\u0627\u0644\u0629."},
gLj(){return"\u0627\u0644\u0633\u0645\u0627\u062d \u0628\u0627\u0644\u0645\u0631\u0641\u0642\u0627\u062a"},
gLk(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0631\u0626\u064a\u0633\u064a \u2014 \u0627\u0644\u0625\u064a\u0642\u0627\u0641 \u064a\u062e\u0641\u064a \u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0625\u0631\u0641\u0627\u0642 \u0623\u064a \u0634\u064a\u0621 \u0641\u064a \u0643\u0644 \u0645\u0643\u0627\u0646\u060c \u0628\u063a\u0636 \u0627\u0644\u0646\u0638\u0631 \u0639\u0646 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0623\u0631\u0628\u0639\u0629 \u0623\u062f\u0646\u0627\u0647."},
gLr(){return"\u0627\u0644\u0633\u0645\u0627\u062d \u0628\u0627\u0644\u0635\u0648\u0631"},
gLs(){return"\u0627\u0644\u062a\u0642\u0627\u0637 \u0627\u0644\u0635\u0648\u0631 \u0648\u062a\u062d\u0645\u064a\u0644\u0647\u0627."},
gLv(){return"\u0627\u0644\u0633\u0645\u0627\u062d \u0628\u0627\u0644\u0641\u064a\u062f\u064a\u0648"},
gLw(){return"\u0645\u064f\u0648\u0642\u064e\u0641 \u0627\u0641\u062a\u0631\u0627\u0636\u064a\u064b\u0627 \u0644\u0623\u064a \u0641\u0631\u0639 \u062c\u062f\u064a\u062f \u2014 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0644\u0627 \u064a\u0645\u0643\u0646 \u0636\u063a\u0637\u0647 \u0642\u0628\u0644 \u0627\u0644\u0631\u0641\u0639\u060c \u0644\u0630\u0627 \u0641\u0647\u0648 \u0623\u0643\u0628\u0631 \u0645\u0633\u062a\u0647\u0644\u0643 \u0644\u062d\u062f \u0627\u0644\u0646\u0642\u0644 \u0627\u0644\u0645\u062c\u0627\u0646\u064a \u0641\u064a Supabase."},
