ga_x(){return"\u06a9\u06d5\u06cc\u0633\u06cc \u0646\u0648\u06ce"},
ga_C(){return"\u06a9\u06d5\u06cc\u0633\u06d5 \u062f\u0648\u0627\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u0648 \u062f\u0627\u0647\u0627\u062a\u0648\u0648\u06d5\u06a9\u0627\u0646"},
ga_y(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0646\u06cc\u06cc\u06d5."},
gUS(){return"\u0628\u06c6\u0631\u062f\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646"},
